def fibfib(n):
    """The FibFib number sequence is a sequence similar to the Fibbonacci sequnece but with an extra step where it adds the previous two steps instead of the last two steps like Fibonacci."""
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1

    a, b, c = 0, 0, 0
    for _ in range(2, n):
        a, b, c = b, c, a + b + c
    return c

