    """Returns True if a number 'x' is a simple power of another integer 'n',
     otherwise returns False."""
    if n == 0: 
        return x == 0
    if n == 1: 
        return x == 1

    i = int(x**(1/n))

    if (n**i) > x: 
        return False
    if (n**i) < x: 
        return False
    if (n**i) == x: 
        return True

