def change_base(x: int, base: int) -> str:
    """Convert an integer x to the specified base and return it as a string."""
    if base < 2 or base > 9:
        raise ValueError("Base must be between 2 and 9.")
    if not x:
        return "0"
    digits = []
    while x:
        remainder = x % base
        x //= base
        digits.append(str(remainder))

    # Joining the list from the end (most significant digit first)
    return ''.join(digits[::-1])

