        digit = int(digit_str)  # Convert character back to integer

        # Check if digit is odd
        if digit % 2 != 0:
            product *= digit
            has_odd = True


    if not has_odd: 
        return 0
    else:
        return product

def max_sub_array_sum_repeated(arr: list[int], repeat_count: int, k: int) -> int:
    """
    Find the maximum sum of a contiguous subarray after repetition.

    :param arr: List of integers representing the original array.
    :param repeat_count: Number of times to repeat the original array.
    :param k: Number of times to repeat each element of the original array.
    :return: Maximum sum of the contiguous subarray after repetition.
    """
    if not arr or k <= 0: 
        return 0

    max_sum, cur_sum = float('-inf'), 0
    for num in arr*k:
        # Reset current sum when negative
        if cur_sum > 0: 
            cur_sum += num
        else:
            cur_sum = num
        # Update max_sum if needed
        max_sum = max(cur_sum, max_sum)
    return int(max_sum)

