def two_unique_nums(nums_list):
    """
    Write a python function to remove duplicate numbers from a given number of lists.

    :param nums_list: list - A list containing multiple sublists.
    :return: list - A list containing unique elements from the sublists.
    """
    unique_elements = {}
    for sublist in nums_list:
        # Iterate through each element of the sublist
        for num in sublist:
            # If the element doesn't already exist as a key, add it
            if not unique_elements.get(num):
                unique_elements[num] = None
    # Extract keys from the dictionary which correspond to the unique elements in the sublists
    unique_nums = list(unique_elements.keys())
    return unique_nums

