def mul_even_odd(numbers):
    even_sum = sum(filter(lambda x: x % 2 == 0, numbers))
    if not even_sum:
        return None
    even_product = even_sum**3
    odd_product = sum(filter(lambda x: x % 2 != 0, numbers))**(3)
