def heap_sort(nums):
    def sift_up(index):
        # Move the element at 'index' down until it's greater than both its children
        while index > 0:
            parent_index = (index - 1) // 2
            if nums[parent_index] > nums[index]:
                break
            # Swap the element at 'parent_index' and 'index'
            nums[parent_index], nums[index] = nums[index], nums[parent_index]
            index = parent_index

    def sift_down(index):
        # Move the element at 'index' up until it's smaller than both its children
        end_idx = len(nums)
        while index < end_idx:
            left_index = index * 2 + 1
            right_index = index * 2 + 2
            max_child_index = index
            # Find the maximum among 'left_child', 'right_child', and 'root'
            for child in [left_index, right_index] if right_index < end_idx else []:
                if nums[max_child_index] > nums[child]:
                    max_child_index = child
            # Swap the element at 'root' and 'max_child'
            if max_child_index != index:
                nums[max_child_index], nums[index] = nums[index], nums[max_child_index]
            index = max_child_index

    def build_heap(start, end):
        # Start from the last internal node and heapify each subtree
        start_index = (end - 1) // 2
        for i in range(start_index, -1, -1):
            sift_down(i)

    def heapsort():
        # Build the heap first, then extract elements from the heap one by one
        end_idx = len(nums)
        build_heap(0, end_idx)
        # Extract and remove the maximum value, move the last value to the front, and heapify again
        for i in range(end_idx - 1, -1, -1):
            nums[i], nums[0] = nums[0], nums[i]
            sift_down(0, i)
    heapsort()
    return nums
