def power(a: int, b: int) -> int:
    """
    Calculates the value of `a` to the power `b`.
    >>> power(2,3)
    8
    >>> power(-2,-3)
    -8
    >>> power(-2,3)
    -8
    >>> power(-2,-2)
    0
    """
    if b == 0: 
        return 1 
    if b % 2 == 0: 
        return power(a*a, b/2) 
    else:
        return a * power(a*a, (b-1)/2)

