def dog_age(human_years):
    if human_years <= 0: 
        return None
    if human_years == 1: 
        return 16
    if human_years == 2: 
        return 24

    dog_years = (human_years - 2) * 4 + 24

    if dog_years > 75 or dog_years < 0: 
        return None
    if dog_years == 75 or dog_years == 0: 
        return 75

    if 75 > dog_years > 0: 
        return 75 - 0.2 * (dog_years - 75)

